add_action( 'template_redirect', 'perfectpixel_redirect_past_buyers' );

function perfectpixel_redirect_past_buyers() {
	if ( ! function_exists( 'is_product' ) || ! is_product() || ! is_user_logged_in() ) {
		return;
	}
	$product_id = get_queried_object_id();
	if ( ! in_array( $product_id, wp_parse_id_list( '{{past_buyer_redirect_ids}}' ), true ) ) {
		return;
	}
	$user = wp_get_current_user();
	if ( wc_customer_bought_product( $user->user_email, $user->ID, $product_id ) ) {
		$url = '{{past_buyer_redirect_url}}';
		wp_safe_redirect( 0 === strpos( $url, '/' ) ? home_url( $url ) : $url );
		exit;
	}
}
